const DB='nextrole-resume-file',STORE='files';
async function open(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>r.result.createObjectStore(STORE);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('Browser file storage is unavailable.'));});}
async function hash(text){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)))].map(n=>n.toString(16).padStart(2,'0')).join('');}
async function transact(mode,operation){const db=await open();try{return await new Promise((resolve,reject)=>{const tx=db.transaction(STORE,mode),request=operation(tx.objectStore(STORE));tx.oncomplete=()=>resolve(request?.result);tx.onerror=()=>reject(Error('Could not save the resume in this browser.'));tx.onabort=()=>reject(Error('Could not save the resume in this browser.'));});}finally{db.close();}}
export async function retainResumeFile(file,text){try{if(!/^.+\.(pdf|docx)$/i.test(file.name)||file.size>5*1024*1024){await clearResumeFile();return false;}const record={name:file.name,type:file.type,blob:file,savedAt:Date.now(),sourceHash:await hash(text)};await transact('readwrite',store=>store.put(record,'resume'));return true;}catch{await clearResumeFile();return false;}}
export async function retainedResumeMetadata(text){try{const record=await transact('readonly',store=>store.get('resume'));if(!record?.blob)return null;return {name:record.name,size:record.blob.size,savedAt:record.savedAt||null,matchesSource:record.sourceHash===await hash(text)};}catch{return null;}}
export async function retainedResumeFile(text){try{const record=await transact('readonly',store=>store.get('resume'));if(!record?.blob||record.sourceHash!==await hash(text))return null;return new File([record.blob],record.name,{type:record.type});}catch{return null;}}
export async function clearResumeFile(){try{await transact('readwrite',store=>store.delete('resume'));return true;}catch{return false;}}
